package ai.decisionos.aside;
import android.app.*;import android.content.*;import android.view.*;import android.view.accessibility.AccessibilityNodeInfo;import org.json.*;
/** Own temporary goal only. Never confirms product handoff or payment. */
final class GoalFlowChecks {
 final Instrumentation i;int checks=0;GoalFlowChecks(Instrumentation i){this.i=i;}
 void check(boolean value,String name){checks++;if(!value)throw new AssertionError(name);}
 void idle(){i.waitForIdleSync();android.os.SystemClock.sleep(250);}
 boolean visible(String s){AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();return root!=null&&!root.findAccessibilityNodeInfosByText(s).isEmpty();}
 void cancel(){AccessibilityNodeInfo root=i.getUiAutomation().getRootInActiveWindow();for(AccessibilityNodeInfo n:root.findAccessibilityNodeInfosByText("취소"))if("취소".equals(String.valueOf(n.getText()))&&n.isClickable()){check(n.performAction(AccessibilityNodeInfo.ACTION_CLICK),"cancel click");idle();return;}throw new AssertionError("cancel missing");}
 boolean contains(View v,String s){if(v instanceof android.widget.TextView&&s.equals(((android.widget.TextView)v).getText().toString()))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int n=0;n<g.getChildCount();n++)if(contains(g.getChildAt(n),s))return true;}return false;}
 GoalAgentActivity launch(String gid){Intent intent=new Intent(i.getTargetContext(),GoalAgentActivity.class);intent.putExtra("goal_id",gid);intent.putExtra("companion_page","준비물");intent.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);GoalAgentActivity a=(GoalAgentActivity)i.startActivitySync(intent);idle();return a;}
 static int run(Instrumentation i)throws Exception{return new GoalFlowChecks(i).execute();}
 int execute()throws Exception{GoalAgentActivity activity=null;String gid=null;try(GoalStore s=new GoalStore(i.getTargetContext())){gid=s.create("fitness","REGRESSION_FLOW_TEMP","운동",0).optString("id");try{
  activity=launch(gid);final CompanionGoalTools a=activity.chat.companion.goalTools;JSONObject o=new JSONObject();GoalStore.put(o,"id","regression-offer-"+gid);GoalStore.put(o,"title","회귀검사 · 결제하지 않음");GoalStore.put(o,"url","https://m.11st.co.kr/products/ma/5741335330");GoalStore.put(o,"priceText","미확인");GoalStore.put(o,"checkedAt",1);s.save("offers",gid,o);
  i.runOnMainSync(()->a.checkout(o));idle();check(visible("상품 화면으로 이동"),"initial confirmation");String key=s.list("intents",gid).get(0).optString("idempotencyKey");cancel();check(s.list("intents",gid).get(0).optString("state").equals("draft"),"cancel saves draft");
  i.runOnMainSync(()->a.checkout(o));idle();check(visible("상품 화면으로 이동"),"cancel permits retry");check(s.list("intents",gid).size()==1&&key.equals(s.list("intents",gid).get(0).optString("idempotencyKey")),"reuse idempotency key");
  i.runOnMainSync(()->a.checkout(o));idle();check(s.list("intents",gid).size()==1,"double tap creates no second intent");i.sendKeyDownUpSync(KeyEvent.KEYCODE_BACK);idle();check(s.list("intents",gid).get(0).optString("state").equals("draft"),"back dismiss saves draft");i.runOnMainSync(()->a.checkout(o));idle();check(visible("상품 화면으로 이동"),"back permits retry");cancel();
  final GoalAgentActivity first=activity;i.runOnMainSync(first::finish);idle();JSONObject pending=s.list("intents",gid).get(0);GoalStore.put(pending,"state","awaiting_confirmation");s.save("intents",gid,pending);activity=launch(gid);final CompanionGoalTools reopened=activity.chat.companion.goalTools;i.runOnMainSync(()->reopened.resumeCheckout(pending));idle();check(visible("상품 화면으로 이동"),"persisted pending intent resumes after activity restart");check(s.list("intents",gid).size()==1,"restart keeps single intent");cancel();
  JSONObject saved=new JSONObject();GoalStore.put(saved,"title","SAVED_FROM_ANOTHER_QUERY");GoalStore.put(saved,"query","비슷한 콘텐츠 제목");GoalStore.put(saved,"saved",true);GoalStore.put(saved,"url","https://www.youtube.com/watch?v=regression");GoalStore.put(saved,"kind","영상");GoalStore.put(saved,"provider","YouTube");String id=s.save("contents",gid,saved);ContentValues older=new ContentValues();older.put("updated",1);s.getWritableDatabase().update("contents",older,"id=?",new String[]{id});
  s.getWritableDatabase().beginTransaction();try{for(int n=0;n<205;n++){JSONObject row=new JSONObject();GoalStore.put(row,"title","UNSAVED_"+n);GoalStore.put(row,"query","다른 검색");s.save("contents",gid,row);}s.getWritableDatabase().setTransactionSuccessful();}finally{s.getWritableDatabase().endTransaction();}
  check(s.contents(gid,"현재 검색",true).size()==1,"saved filter before 200 row cap");check(s.contents(gid,"현재 검색",false).isEmpty(),"discovery still respects current query");
  i.runOnMainSync(()->{reopened.ui.page="미디어";reopened.tab=0;GoalStore.put(reopened.g,"savedOnly",true);reopened.store.saveGoal(reopened.g);reopened.render();});idle();final boolean[] shown={false};i.runOnMainSync(()->shown[0]=contains(reopened.ui.sideBody,"SAVED_FROM_ANOTHER_QUERY"));check(shown[0],"saved-only UI includes different query");GoalStore.put(saved,"hidden",true);s.save("contents",gid,saved);check(s.contents(gid,"현재 검색",true).isEmpty(),"hidden saved record excluded");
 }finally{if(activity!=null){final Activity a=activity;i.runOnMainSync(a::finish);idle();}if(gid!=null)s.deleteGoal(gid);}}return checks;}
}
